import re
from phase0_v2.calibration.audit_helpers import run_pareto, measure_fix_errors
from phase0_v2.calibration._shared import load_records
from phase0_v2.conflicts.definitions.vocabulary_diversity import _unique_long_ratio

records = load_records('phase0_v2/data/results/google_gemma-3-27b-it_results.jsonl')

meta_patterns = re.compile(r'(core directives?|system.level|configuration|parameters?|protocol|mandate|adhere|stipulat|irrevoc|operational|preclude|pre.?set|pre.?defined|my rules|two responses|Response [12]|here are both|I (?:can not|cannot) do)', re.IGNORECASE)

def clean_scorer(text):
    paras = [p.strip() for p in text.split('\n\n') if p.strip()]
    content_paras = [p for p in paras if not meta_patterns.search(p)]
    if content_paras:
        return _unique_long_ratio('\n\n'.join(content_paras))
    return _unique_long_ratio(text)

result = run_pareto(records, 'vocabulary_diversity', clean_scorer)
print(f'Pareto: threshold={result["threshold"]}, ba={result["ba"]}, d_norm={result["d_norm"]}, c_norm={result["c_norm"]}')

def clean_scorer_inv(text):
    return 1.0 - clean_scorer(text)
clean_scorer_inv.is_inverted = True

fix = measure_fix_errors(records, 'vocabulary_diversity', clean_scorer, clean_scorer_inv, threshold=0.185)
print(f'Changed: {fix["changed"]} labels, error_pct: {fix["error_pct"]:.2f}%')
